//! API features (ADR 0016) through the library entry point: which tables
//! get one and with which files, `[api.skip]` and `[api.exclude]`, and
//! stale generated files under `api.output` and `shared/`. The features'
//! behaviour is tested by compiling and running them in `tests/api-app`.

use std::fs;
use std::path::PathBuf;

use anyhow::Result;
use rok_sqlc::{ApiConfig, ApiEndpoint, Config, Derive, Extractor};
use tempfile::TempDir;

const SCHEMA: &str = "CREATE TABLE users (id UUID PRIMARY KEY, email TEXT NOT NULL);
CREATE TABLE posts (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE tags (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE post_tags (
    post_id BIGINT NOT NULL REFERENCES posts (id),
    tag_id BIGINT NOT NULL REFERENCES tags (id),
    PRIMARY KEY (post_id, tag_id)
);
CREATE TABLE events (kind TEXT NOT NULL);
";

/// The files of a feature, besides the user's `service.rs`.
const FEATURE_FILES: [&str; 7] = [
    "dto.rs",
    "handlers.rs",
    "mod.rs",
    "model.rs",
    "repo.rs",
    "routes.rs",
    "service_api.rs",
];

struct Project {
    dir: TempDir,
}

impl Project {
    fn new(schema: &str) -> Result<Self> {
        let dir = TempDir::new()?;
        fs::write(dir.path().join("schema.sql"), schema)?;
        Ok(Project { dir })
    }

    fn path(&self, path: &str) -> PathBuf {
        self.dir.path().join(path)
    }

    fn read(&self, path: &str) -> Result<String> {
        Ok(fs::read_to_string(self.path(path))?)
    }

    /// The configuration `rok-sqlc init` writes, generating `src/db` and
    /// the features in `src/features`.
    fn config(&self) -> Config {
        let mut config = Config::default();
        config.schema = vec![self.path("schema.sql")];
        config.output = self.path("src/db");
        config.derive = vec![Derive::Serde, Derive::Validate];
        config.extractors = vec![Extractor::ActixWeb];
        config.api = Some(ApiConfig::new(self.path("src/features")));
        config
    }
}

fn api(config: &mut Config) -> &mut ApiConfig {
    config.api.as_mut().expect("the API is configured")
}

/// A schema with ticket 08's shapes: `users` soft-deletes and has unique
/// columns, one hidden; `posts` is versioned and tenant-scoped, belongs to
/// its author and has many `tags`, through `post_tags`.
const EXTENDED: &str = "CREATE TABLE users (
    id UUID PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    token TEXT UNIQUE,
    deleted_at TIMESTAMPTZ
);
CREATE TABLE posts (
    id BIGSERIAL PRIMARY KEY,
    tenant_id UUID NOT NULL,
    author_id UUID NOT NULL REFERENCES users (id),
    title TEXT NOT NULL,
    revision BIGINT NOT NULL DEFAULT 1
);
CREATE TABLE tags (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE post_tags (
    post_id BIGINT NOT NULL REFERENCES posts (id),
    tag_id BIGINT NOT NULL REFERENCES tags (id),
    PRIMARY KEY (post_id, tag_id)
);
";

/// The configuration of [`EXTENDED`]: its conventions, and `users`
/// public, hiding `token`.
fn extended(project: &Project) -> Config {
    let mut config = project.config();
    config.conventions.tenant_column = Some("tenant_id".into());
    config.conventions.version_column = Some("revision".into());
    config.conventions.soft_delete_column = Some("deleted_at".into());
    api(&mut config)
        .hidden
        .insert("users".into(), vec!["token".into()]);
    config
}

#[test]
fn each_table_but_join_tables_and_excluded_ones_gets_a_feature() -> Result<()> {
    let project = Project::new(SCHEMA)?;
    let mut config = project.config();
    api(&mut config).exclude.push("tags".into());
    let report = rok_sqlc::generate(&config)?;

    for feature in ["users", "posts", "events"] {
        for file in FEATURE_FILES {
            let path = project.path(&format!("src/features/{feature}/{file}"));
            let text = fs::read_to_string(&path)?;
            assert!(text.starts_with("// @generated by rok-sqlc"), "{path:?}");
            assert!(report.written.contains(&path), "{path:?}");
        }
        let service = project.path(&format!("src/features/{feature}/service.rs"));
        assert!(report.scaffolded.contains(&service), "{service:?}");
        assert!(
            fs::read_to_string(&service)?.starts_with("// Scaffolded once by rok-sqlc"),
            "{service:?}"
        );
    }
    for absent in ["tags", "post_tags"] {
        assert!(!project.path(&format!("src/features/{absent}")).exists());
    }
    let generated = project.read("src/features/generated.rs")?;
    for module in ["events", "posts", "users"] {
        assert!(
            generated.contains(&format!("#[path = \"{module}/mod.rs\"]\npub mod {module};")),
            "{generated}"
        );
        assert!(
            generated.contains(&format!("{module}::routes(cfg);")),
            "{generated}"
        );
    }
    // No `tags` or `post_tags` module (`tags(...)` is the document's).
    for absent in ["mod tags;", "mod post_tags;", "tags::"] {
        assert!(!generated.contains(absent), "{absent}\n{generated}");
    }
    assert!(
        generated.contains("pub fn register_services(cfg: &mut web::ServiceConfig, pool: &PgPool)")
    );
    assert!(generated.contains("pub fn configure_all(cfg: &mut web::ServiceConfig)"));
    let readme = project.read("src/features/README.md")?;
    assert!(
        readme.starts_with("<!-- @generated by rok-sqlc"),
        "{readme}"
    );
    assert!(readme.contains("| `users` | `/api/v1/users` |"), "{readme}");

    // The data layer's list reads exist for the features only.
    assert!(project.path("src/db/users/listing.rs").is_file());
    assert!(!project.path("src/db/tags/listing.rs").exists());
    assert!(!project.path("src/db/post_tags/listing.rs").exists());
    assert!(
        project
            .read("src/db/users/mod.rs")?
            .contains("pub mod listing;")
    );
    Ok(())
}

#[test]
fn a_table_without_a_key_serves_list_and_create_and_skips_drop_methods() -> Result<()> {
    let project = Project::new(SCHEMA)?;
    let mut config = project.config();
    api(&mut config)
        .skip
        .insert("posts".into(), vec![ApiEndpoint::Remove, ApiEndpoint::List]);
    rok_sqlc::generate(&config)?;

    let routes = project.read("src/features/events/routes.rs")?;
    assert!(routes.contains("web::get().to(handlers::list)"), "{routes}");
    assert!(
        routes.contains("web::post().to(handlers::create)"),
        "{routes}"
    );
    assert!(!routes.contains("{id}"), "{routes}");
    let service = project.read("src/features/events/service_api.rs")?;
    assert!(!service.contains("fn get_one"), "{service}");

    let routes = project.read("src/features/posts/routes.rs")?;
    assert!(!routes.contains("handlers::remove"), "{routes}");
    assert!(!routes.contains("handlers::list)"), "{routes}");
    assert!(routes.contains("handlers::update"), "{routes}");
    let service = project.read("src/features/posts/service_api.rs")?;
    for gone in ["fn remove(", "fn remove_in(", "fn list("] {
        assert!(!service.contains(gone), "{service}");
    }
    assert!(service.contains("async fn update_in("), "{service}");
    // No list reads: its listing holds only its many-to-many writes.
    let listing = project.read("src/db/posts/listing.rs")?;
    assert!(!listing.contains("list_matching"), "{listing}");
    assert!(listing.contains("pub async fn attach_tags"), "{listing}");
    Ok(())
}

/// A feature serving only its list declares no `404` helper, which nothing
/// would call: `-D warnings` rejects dead code.
#[test]
fn a_list_only_feature_declares_no_unused_helper() -> Result<()> {
    let project = Project::new(SCHEMA)?;
    let mut config = project.config();
    api(&mut config).skip.insert(
        "users".into(),
        vec![
            ApiEndpoint::Create,
            ApiEndpoint::GetOne,
            ApiEndpoint::Update,
            ApiEndpoint::Remove,
        ],
    );
    rok_sqlc::generate(&config)?;
    let service = project.read("src/features/users/service_api.rs")?;
    assert!(service.contains("async fn list("), "{service}");
    assert!(!service.contains("not_found"), "{service}");
    // A feature reading its rows by key keeps it.
    let service = project.read("src/features/posts/service_api.rs")?;
    assert!(service.contains("fn not_found() -> AppError"), "{service}");
    Ok(())
}

/// Generated files under `api.output` and the generated tools in `shared/`
/// are stale once nothing plans them, like `db/`'s; the user's files there,
/// scaffolded `service.rs` files included, never are.
#[test]
fn stale_features_and_shared_tools_are_removed_but_never_the_users_files() -> Result<()> {
    let project = Project::new(SCHEMA)?;
    let config = project.config();
    rok_sqlc::generate(&config)?;
    let service = project.path("src/features/posts/service.rs");
    fs::write(&service, "// mine now\n")?;
    let mine = project.path("src/features/posts/notes.txt");
    fs::write(&mine, "kept")?;
    let old_tool = project.path("src/shared/retired.rs");
    fs::write(
        &old_tool,
        "// @generated by rok-sqlc. Do not edit by hand.\n",
    )?;
    let own_tool = project.path("src/shared/mail.rs");
    fs::write(&own_tool, "//! My mailer.\n")?;

    fs::write(
        project.path("schema.sql"),
        SCHEMA
            .replace("CREATE TABLE posts", "CREATE TABLE articles")
            .replace("REFERENCES posts", "REFERENCES articles"),
    )?;
    let mut check = config.clone();
    check.check = true;
    let error = rok_sqlc::generate(&check).unwrap_err();
    assert!(error.report().stale.contains(&old_tool), "{error:?}");
    assert!(
        error
            .report()
            .stale
            .contains(&project.path("src/features/posts/handlers.rs")),
        "{error:?}"
    );

    let report = rok_sqlc::generate(&config)?;
    for file in FEATURE_FILES {
        let path = project.path(&format!("src/features/posts/{file}"));
        assert!(report.stale.contains(&path), "{path:?}");
        assert!(!path.exists(), "{path:?}");
    }
    assert!(report.stale.contains(&old_tool));
    assert!(!old_tool.exists());
    assert_eq!(fs::read_to_string(&service)?, "// mine now\n");
    assert!(mine.is_file() && own_tool.is_file());
    assert!(!report.stale.contains(&service));
    assert!(project.path("src/features/articles/handlers.rs").is_file());
    assert!(!project.read("src/features/generated.rs")?.contains("posts"));
    Ok(())
}

/// Ticket 08's routes follow the schema: a `by-` route per unique column
/// that isn't hidden, `restore` on a soft-delete table, `/search` only
/// when `api.search_endpoint` is set, relationship routes to tables with a
/// feature, and `If-Match` and the `Tenant` on a versioned tenant table.
#[test]
fn extended_routes_follow_the_schema() -> Result<()> {
    let project = Project::new(EXTENDED)?;
    let mut config = extended(&project);
    rok_sqlc::generate(&config)?;
    let routes = project.read("src/features/users/routes.rs")?;
    for route in [
        "\"/by-email/{value}\", web::get().to(handlers::get_by_email)",
        "\"/{id}/restore\", web::post().to(handlers::restore)",
        "\"/{id}/posts\", web::get().to(handlers::list_posts)",
    ] {
        assert!(routes.contains(route), "{routes}");
    }
    assert!(!routes.contains("by-token"), "{routes}");
    assert!(!routes.contains("/search"), "{routes}");
    let routes = project.read("src/features/posts/routes.rs")?;
    assert!(
        routes.contains("\"/{id}/tags\", web::put().to(handlers::sync_tags)"),
        "{routes}"
    );
    let routes = project.read("src/features/tags/routes.rs")?;
    // Only the join table's first key column's side syncs.
    assert!(!routes.contains("sync_posts"), "{routes}");
    assert!(routes.contains("handlers::attach_posts"), "{routes}");
    let handlers = project.read("src/features/posts/handlers.rs")?;
    assert!(handlers.contains("version: IfMatch<i64>"), "{handlers}");
    assert!(
        handlers.contains("tenant: Tenant<uuid::Uuid>"),
        "{handlers}"
    );
    assert!(
        handlers.contains("query: web::Query<GetPostQuery>"),
        "{handlers}"
    );

    api(&mut config).search_endpoint = true;
    rok_sqlc::generate(&config)?;
    let routes = project.read("src/features/users/routes.rs")?;
    assert!(
        routes.contains("\"/search\", web::post().to(handlers::search)"),
        "{routes}"
    );
    let dto = project.read("src/features/users/dto.rs")?;
    assert!(
        dto.contains("pub token: Option<serde_json::Value>"),
        "{dto}"
    );
    Ok(())
}

#[test]
fn skip_and_relationship_opt_outs_drop_the_extended_routes() -> Result<()> {
    let project = Project::new(EXTENDED)?;
    let mut config = extended(&project);
    api(&mut config).search_endpoint = true;
    api(&mut config).skip.insert(
        "users".into(),
        vec![
            ApiEndpoint::Lookups,
            ApiEndpoint::Restore,
            ApiEndpoint::Search,
            ApiEndpoint::Relationships,
        ],
    );
    config.relationships.insert(
        "post_tags".into(),
        [("tag".to_owned(), rok_sqlc::RelationshipChange::OptOut)].into(),
    );
    rok_sqlc::generate(&config)?;
    let routes = project.read("src/features/users/routes.rs")?;
    for gone in ["by-email", "restore", "/search", "posts"] {
        assert!(!routes.contains(gone), "{gone}: {routes}");
    }
    // `posts` still reaches its author.
    let dto = project.read("src/features/posts/dto.rs")?;
    assert!(dto.contains("pub enum PostInclude"), "{dto}");
    // Without the pair, `post_tags` is no join table: no many-to-many.
    let routes = project.read("src/features/posts/routes.rs")?;
    assert!(!routes.contains("\"/{id}/tags"), "{routes}");
    Ok(())
}

/// Generated features are laid out as rustfmt lays them out, whatever the
/// length of the names: here long ones, which wrap signatures, `use` lists,
/// struct literals and the `Location` of a composite text key.
#[test]
fn features_with_long_names_are_rustfmt_clean() -> Result<()> {
    let project = Project::new(
        "CREATE TABLE organization_membership_invitations (
    organization_identifier TEXT NOT NULL,
    invited_email_address_of_the_person TEXT NOT NULL,
    invitation_message_written_by_the_inviter TEXT,
    PRIMARY KEY (organization_identifier, invited_email_address_of_the_person)
);
CREATE TABLE x (id BIGSERIAL PRIMARY KEY, n INT NOT NULL);
CREATE TABLE quarterly_financial_statement_documents (
    statement_document_identifier UUID PRIMARY KEY,
    tenant_id UUID NOT NULL,
    responsible_accountant_owner_id UUID NOT NULL,
    organization_identifier TEXT,
    invited_email_address_of_the_person TEXT,
    externally_visible_reference_code TEXT NOT NULL,
    revision BIGINT NOT NULL DEFAULT 1,
    deleted_at TIMESTAMPTZ,
    FOREIGN KEY (organization_identifier, invited_email_address_of_the_person)
        REFERENCES organization_membership_invitations (organization_identifier, invited_email_address_of_the_person),
    UNIQUE (tenant_id, externally_visible_reference_code)
);
CREATE TABLE financial_statement_review_categories (
    review_category_identifier BIGSERIAL PRIMARY KEY,
    tenant_id UUID NOT NULL,
    descriptive_category_label TEXT NOT NULL UNIQUE
);
CREATE TABLE statement_document_review_category_pairings (
    statement_document_identifier UUID NOT NULL REFERENCES quarterly_financial_statement_documents (statement_document_identifier),
    review_category_identifier BIGINT NOT NULL REFERENCES financial_statement_review_categories (review_category_identifier),
    tenant_id UUID NOT NULL,
    PRIMARY KEY (tenant_id, statement_document_identifier, review_category_identifier)
);
",
    )?;
    let mut config = project.config();
    // Ticket 08's routes, with long names: lookups, search, soft delete,
    // versions, tenants, owners, and relationships of every kind.
    config.conventions.tenant_column = Some("tenant_id".into());
    config.conventions.version_column = Some("revision".into());
    config.conventions.soft_delete_column = Some("deleted_at".into());
    api(&mut config).search_endpoint = true;
    api(&mut config).access.insert(
        "quarterly_financial_statement_documents".into(),
        rok_sqlc::ApiAccess::Admin,
    );
    api(&mut config).owner.insert(
        "quarterly_financial_statement_documents".into(),
        "responsible_accountant_owner_id".into(),
    );
    api(&mut config).hidden.insert(
        "financial_statement_review_categories".into(),
        vec!["descriptive_category_label".into()],
    );
    api(&mut config).search.insert(
        "organization_membership_invitations".into(),
        vec![
            "invited_email_address_of_the_person".into(),
            "invitation_message_written_by_the_inviter".into(),
            "organization_identifier".into(),
        ],
    );
    let report = rok_sqlc::generate(&config)?;
    // The features and the list reads (the rest of the data layer has its
    // own tests).
    let features = project.path("src/features");
    let files: Vec<&PathBuf> = report
        .written
        .iter()
        .chain(&report.scaffolded)
        .filter(|path| path.extension().is_some_and(|ext| ext == "rs"))
        .filter(|path| path.starts_with(&features) || path.ends_with("listing.rs"))
        .collect();
    let output = std::process::Command::new("rustfmt")
        .args(["--edition", "2024", "--check"])
        .args(&files)
        .output()?;
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stdout)
    );
    Ok(())
}
